from pathlib import Path
import h5py
files = [f for f in Path('/tmp/data_files.txt').read_text().splitlines() if f.endswith('.nwb')]
if not files:
    raise SystemExit('no nwb files')
fpath = files[0]
print('FILE', fpath)
with h5py.File(fpath, 'r') as f:
    for grp in ['intervals', 'processing/behavior', 'processing/ophys', 'stimulus/presentation', 'general/subject']:
        print(f'===== {grp} =====')
        if grp in f:
            def show(name, obj):
                rel = name[len(grp):].lstrip('/')
                if rel.count('/') <= 2:
                    print(name, type(obj).__name__)
            f[grp].visititems(lambda name, obj: show(grp + '/' + name, obj))
        else:
            print('MISSING')
